  async function updateHomeContent(html = 1, activity = 3) {
    var homeKey = 'masterContent-'+(feedType??0);
    var watchKey = watchListCacheKey;
    var sess_id = "<?= $this->session->profile_id ?? 0 ?>";
    
    if (sess_id != 0) {
      const [homeData, watchData] = await Promise.all([fetchCacheData(homeKey), fetchCacheData(watchKey)]);
      try {
        var findInWatch = [];
        homeData.data.home_data.data.forEach((citem, ckey) => {
          citem.list.forEach((sitem, skey) => {
            var found = false;
            if (watchData) {
              watchData.data.forEach((item, key) => {
                if (item.show_id == sitem.id && item.is_deleted != 1) {
                  found = true;
                  homeData.data.home_data.data[ckey].list[skey].in_watchlist = 1;
                }
              });
            }
            if (!found && activity != 1) {
              homeData.data.home_data.data[ckey].list[skey].in_watchlist = 0;
              findInWatch.push(sitem.id);
            }
          });
        });

        

        if (findInWatch.length > 0) {
          const isaddedInWatchlist = await getWatchlistById(findInWatch);
          if (isaddedInWatchlist) {
            homeData.data.home_data.data.forEach((citem, ckey) => {
              citem.list.forEach((sitem, skey) => {
                isaddedInWatchlist.forEach((item, key) => {
                  if (item.show_id == sitem.id && item.isOnWatchlist == 1) {
                    homeData.data.home_data.data[ckey].list[skey].in_watchlist = 1;
                  }
                });
              });
            });
          }
        }

        var cache = await caches.open('appCache');
        await cache.put(homeKey, new Response(JSON.stringify(homeData)));
        if (html == 1) {
          renderTrendingSections(homeData.data.home_data.data);
        }
      } catch (error) {
       // console.error('Error updating home content:', error);
      }
    }
  }

