  function manage_section_visibility(){
    $('section').removeClass('banner-bottom-sec');
    const bannerSection = document.querySelector('.banner_after_navbar');
    if (bannerSection) {
        let nextSibling = bannerSection.nextElementSibling;
        while (nextSibling) {
            const style = window.getComputedStyle(nextSibling);
            if (style.display !== 'none') {
                nextSibling.classList.add('banner-bottom-sec');
                break;
            }
            nextSibling = nextSibling.nextElementSibling;
        }
    }
  }

