  function initVideoPlayer(url, id, bannerImg) {
    var videoPlayer = videojs('my_video_' + id);
    videoPlayer.src({
      type: 'application/x-mpegURL',
      src: url
    });
    if (!unmuteSpk) {
      videoPlayer.muted(true);
    }
    videoPlayer.on('ended', function() {
      $('.my_video .vjs-poster').css({
        'background-image': 'url("' + bannerImg + '")',
        'display': 'block'
      });
    });
    return videoPlayer;
  }
  

  var activeBannerPlayers = {};

    function playVideo(url, id, titles_hover, token = null) {
      try {
        // Pause all other active players except the current one
        for (let objKey in activeBannerPlayers) {
          if (objKey !== id) {
            pause_vdo(objKey);
          }
        }

        // Pause the current video if it is already playing
        // if (activeBannerPlayers[id]) {
        //   pause_vdo(id);
        // }

        // Initialize the video player if not already initialized
        if (!activeBannerPlayers[id]) {
          activeBannerPlayers[id] = initBannerPlayer(url, id, token);
        }

        // Get the video element
        var videoElement = document.getElementById('my_video_' + id);
        if (!videoElement) {
          console.error(`Video element not found for ID: my_video_${id}`);
          return;
        }

        // Ensure the video is fully loaded before playing
        videoElement.addEventListener('loadeddata', () => {
          startVideoPlayback(videoElement, id);
        });

        // If the video is already ready, play it immediately
        if (videoElement.readyState >= 2) {     
          startVideoPlayback(videoElement, id);
        }
      } catch (error) {
        console.error("Unexpected error in playVideo function:", error);
      }
    }

    function startVideoPlayback(videoElement, id) { 
      var promise = videoElement.play();

      promise
        .then(() => {
          console.log(`Video with ID: ${id} started playing successfully.`);
          videoElement.classList.add('removeImg');
          videoElement.muted = !unmuteSpk;
        })
        .catch((error) => {
          if (error.name === 'AbortError') {
            console.warn(`Play aborted for video ID: ${id} due to a load request.`);
          } else {
            console.error(`Error while playing video with ID: ${id}`, error);
          }
        });
    }


  async function initBannerPlayer(url, id, token=null) {
    var uri = url;
    var videoElement = document.getElementById('my_video_' + id);
    var videoContainer = document.getElementById("video-container-"+id);
    var player = new shaka.Player(videoElement);
    var browser = Browser;
    if (browser == 2) {

      function getFairplayCert() {
        var xmlhttp;
        if (window.XMLHttpRequest) {
          xmlhttp = new XMLHttpRequest();
        } else {
          xmlhttp = new ActiveXObject("Microsoft.XMLHTTP");
        }
        xmlhttp.open("GET", fairplayCertUri, false);
        xmlhttp.send();

        var fpsCert = shaka.util.Uint8ArrayUtils.fromBase64(xmlhttp.responseText);
        return fpsCert;
      }

      const fairplayCert = getFairplayCert();
      player.configure({
        drm: {
          servers: {

            'com.apple.fps': licenseURI
          },
          advanced: {
            'com.apple.fps': {
              serverCertificate: fairplayCert
            }
          },
        },
        streaming: {
          autoLowLatencyMode: true,
        }
      });

      player.getNetworkingEngine()
      .registerRequestFilter(function(type, request) {
        if (type == shaka.net.NetworkingEngine.RequestType.LICENSE) {
          const originalPayload = new Uint8Array(request.body);
          const base64Payload = shaka.util.Uint8ArrayUtils.toBase64(originalPayload);
          const params = 'spc=' + encodeURIComponent(base64Payload);

          request.body = shaka.util.StringUtils.toUTF8(params);
          request.headers['Content-Type'] = 'application/x-www-form-urlencoded';
          request.headers["pallycon-customdata-v2"] = token;
        }
      });

      player.getNetworkingEngine()
      .registerResponseFilter(function(type, response) {
        // Alias some utilities provided by the library.
        if (type == shaka.net.NetworkingEngine.RequestType.LICENSE) {
          const responseText = shaka.util.StringUtils.fromUTF8(response.data)
            .trim();
          response.data = shaka.util.Uint8ArrayUtils.fromBase64(responseText)
            .buffer;
          parsingResponse(response);
        }
      });

    }else {

      let drmConfig = {
      servers: {
        "com.widevine.alpha": licenseURI,
        // "com.microsoft.playready": licenseURI,
        
      },
      advanced: {
        "com.widevine.alpha": {
          videoRobustness: "SW_SECURE_DECODE", // Specify video robustness level
          audioRobustness: "SW_SECURE_CRYPTO" // Specify audio robustness level
        }
      }
      };
      player.configure({
        drm: drmConfig,
        streaming: {
          autoLowLatencyMode: true
        }
      });

      player.getNetworkingEngine()
      .registerRequestFilter(function(type, request) {
        if (type == shaka.net.NetworkingEngine.RequestType.LICENSE) {
          request.headers["pallycon-customdata-v2"] = token;
        }
      });

    }
    await player.load(uri);    
    if (!unmuteSpke) {
      videoElement.muted = true;
    }
    
    videoElement.addEventListener('loadedmetadata', () => {
        if (Number(nskipable_start) > 0) {
            videoElement.currentTime = Number(nskipable_start);
        }
    });

    videoElement.addEventListener('timeupdate', function onTimeUpdate() {
        if (Number(nskipable_end) > 0 && ((videoElement.duration-Number(nskipable_end)) > Number(nskipable_start)) && videoElement.currentTime >= (videoElement.duration-Number(nskipable_end))) {
            videoElement.pause();
            videoElement.currentTime = Number(nskipable_start);
            videoElement.removeEventListener('timeupdate', onTimeUpdate);
        }
    });

    return player;
  }


