  async function initializePlayer(url, id, token=null) {
    var uri = url;
    var videoElement = document.getElementById('my_showw_' + id);
    var videoContainer = document.getElementById("video-container-"+id);
    var player = new shaka.Player(videoElement);
    var browser = Browser;
    var fairplayCertUri =  "https://license-global.pallycon.com/ri/fpsKeyManager.do?siteId=2LSX";
    var licenseURI = `<?= BASEURLAPI ?><?= BASEVERSION ?>onRequestCreateVideoLicense`;

    if (browser == 2) {

      function getFairplayCert() {
        var xmlhttp;
        if (window.XMLHttpRequest) {
          xmlhttp = new XMLHttpRequest();
        } else {
          xmlhttp = new ActiveXObject("Microsoft.XMLHTTP");
        }
        xmlhttp.open("GET", fairplayCertUri, false);
        xmlhttp.send();

        var fpsCert = shaka.util.Uint8ArrayUtils.fromBase64(xmlhttp.responseText);
        return fpsCert;
      }

      const fairplayCert = getFairplayCert();
      player.configure({
        drm: {
          servers: {

            'com.apple.fps': licenseURI
          },
          advanced: {
            'com.apple.fps': {
              serverCertificate: fairplayCert
            }
          },
        },
        streaming: {
          autoLowLatencyMode: true,
        }
      });

      player.getNetworkingEngine()
      .registerRequestFilter(function(type, request) {
        if (type == shaka.net.NetworkingEngine.RequestType.LICENSE) {
          const originalPayload = new Uint8Array(request.body);
          const base64Payload = shaka.util.Uint8ArrayUtils.toBase64(originalPayload);
          const params = 'spc=' + encodeURIComponent(base64Payload);

          request.body = shaka.util.StringUtils.toUTF8(params);
          request.headers['Content-Type'] = 'application/x-www-form-urlencoded';
          request.headers["pallycon-customdata-v2"] = token;
        }
      });

      player.getNetworkingEngine()
      .registerResponseFilter(function(type, response) {
        // Alias some utilities provided by the library.
        if (type == shaka.net.NetworkingEngine.RequestType.LICENSE) {
          const responseText = shaka.util.StringUtils.fromUTF8(response.data)
            .trim();
          response.data = shaka.util.Uint8ArrayUtils.fromBase64(responseText)
            .buffer;
          parsingResponse(response);
        }
      });

    }else {

      let drmConfig = {
        servers: {
          "com.widevine.alpha": licenseURI,
          // "com.microsoft.playready": licenseURI,
          
        },
        advanced: {
          "com.widevine.alpha": {
            videoRobustness: "SW_SECURE_DECODE", // Specify video robustness level
            audioRobustness: "SW_SECURE_CRYPTO" // Specify audio robustness level
          }
        }
      };
      player.configure({
        drm: drmConfig,
        streaming: {
          autoLowLatencyMode: true
        }
      });

      player.getNetworkingEngine()
      .registerRequestFilter(function(type, request) {
        if (type == shaka.net.NetworkingEngine.RequestType.LICENSE) {
          request.headers["pallycon-customdata-v2"] = token;
        }
      });

    }    
    await player.load(uri);    
    if (!unmuteSpke) {
      videoElement.muted = true;
    }

    videoElement.addEventListener('loadedmetadata', () => {
        if (Number(nskipable_start) > 0) {
            videoElement.currentTime = Number(nskipable_start);
        }
    });

    videoElement.addEventListener('timeupdate', function onTimeUpdate() {
        if (Number(nskipable_end) > 0 && ((videoElement.duration-Number(nskipable_end)) > Number(nskipable_start)) && videoElement.currentTime >= (videoElement.duration-Number(nskipable_end))) {
            videoElement.pause();
            videoElement.currentTime = Number(nskipable_start);
            videoElement.removeEventListener('timeupdate', onTimeUpdate);
        }
    });
    
    return player;
  }

  var showPlayers = {};

  function initshowPlayer(url, id) {
    
    // var videoPlayer = videojs('my_showw_' + id, {
    //   fluid: true
    // });
    if (!unmuteSpke) {
      videoPlayer.muted(true);
    }
    videoPlayer.src({
      type: 'application/x-mpegURL',
      src: url
    });
    videoPlayer.on('ended', function() {
      videoPlayer.posterImage.show();
    });
    return videoPlayer;
  }

  async function playShow(url, id, bannerImg, drm=0, vdcId=0, mediaId=0, owned_by=0, contentId=null, apikey=null) {
    // if (showPlayers[id]) {
    //   pause_show(id, bannerImg);
    // }
    if(showPlayers){
      Object.entries(showPlayers).forEach((item,key)=>{
        let idx = item[0];
        let shwPlayer = document.getElementById('my_showw_' + idx);
        shwPlayer.pause();
      })
    }
    var token = null;
    if (!showPlayers[id]) {
      if(owned_by==0){
        fairplayCertUri =  "https://license-global.pallycon.com/ri/fpsKeyManager.do?siteId=2LSX";
        licenseURI = `<?= BASEURLAPI ?><?= BASEVERSION ?>onRequestCreateVideoLicense`;
        if(drm == 1 && vdcId && mediaId){  
          var data = await getDrmData(vdcId, mediaId);
          if(data.url && data.token){
            fileUrl = data.url;
            token = data.token;
            showPlayers[id] = await initializePlayer(fileUrl, id, token);
          }        
        }else if(url){        
          showPlayers[id] = await initializePlayer(url, id, token);
        }
      }else{
        if(contentId && apikey){
          var data = await getPartnerContent(contentId, apikey);
          if(data){
            if(Browser == 2){
              fairplayCertUri = $data['playUrls'][0]['certificateUrl']??$data['playUrls'][0]['certificateUrl'];
              licenseURI = $data['playUrls'][0]['licenceUrl']??$data['playUrls'][0]['licenceUrl'];
              fileUrl = $data['playUrls'][0]['url']??$data['playUrls'][0]['url'];
              showPlayers[id] = await initializePlayer(fileUrl, id, token);
            }else{
              licenseURI = $data['playUrls'][1]['licenceUrl']??$data['playUrls'][1]['licenceUrl'];
              fileUrl = $data['playUrls'][1]['url']??$data['playUrls'][1]['url'];
              showPlayers[id] = await initializePlayer(fileUrl, id, token);
            }
          }
        }
      }
    }

    var videoPlayer = showPlayers[id];
    var videoElement = document.getElementById('my_showw_' + id);
    if (!videoElement.paused) {
      return;
    }
    
    var promise = new Promise(async function(resolve, reject) {
      try {
        await videoElement.play();
        if (unmuteSpke) {
          videoElement.muted = false;
        } else {
          videoElement.muted = true;
        }
        $('.pb_card_vd-2 .volume_banner_dt').show();
        // videoPlayer.fluid(true);
        resolve();
      } catch (error) {
        reject(error);
      }
    });

    // promise.then(() => {
    //   $('.my_show .vjs-poster').css({
    //     'background-image': 'url("' + bannerImg + '")',
    //     'display': 'none'
    //   });
    // }).catch(function(error) {
    // //  console.error('Error playing video show:', error); // Log any errors that occur during play
    // });
  }



