<script type="text/javascript">

$(document).ready(function() {
    // shimmer('show');
    var feedType = localStorage.getItem('feedType')??'0';
    const homeKey = 'masterContent-'+ feedType;
    fetchCacheData(homeKey)
    .then(async (cache_data) => {
      //console.log("cache_data",cache_data);
          try {
              if (cache_data.data) {
                  const currentTime = Date.now();
                  if (currentTime > cache_data.cacheExpiration) {
                      await handleCacheExpiration(homeKey, cache_data);
                  } else {
                      await handleCachedData(cache_data);
                  }
              } else {
                  fetchMasterContentAndUpdateCache(null, cache_data);
              }
          } catch (error) {
              console.error('Error processing cache data:', error);
              // shimmer('hide');
          }
      })   
  });


  async function fetchHomeFeedWithoutCache(page,itemsPerPage){
    var limit = itemsPerPage;
    var feedType = localStorage.getItem('feedType')??'0';
    try {
      const response = await $.ajax({
        url: `${base_url}web/home/getShorts`,
        type: "post",
        data: { page, limit, feedType}
      });
      const res = JSON.parse(response);
      return res;
    } catch (error) {
      console.warn('Error fetching watching details:', error);
      return '';
    }
  }

  async function checkHomeFeed(shortsData,startsWith,additional_limit=100){
    if (shortsData.totalCount <= startsWith) {
        if (shortsData.stillDataRemains) {
            var feedKey = localStorage.getItem('feedType')??'0';
            const additionalShortsData = await getShortsData(feedKey, (shortsData.totalCount + additional_limit));
            shortsData = additionalShortsData; // Update with new data
        } else {
            // startsWith = startsWith - shortsData.totalCount; // Adjust startsWith if no more data remains
        }
    }
    var res = {
      shortsData,
      startsWith
    }
    return res;
  }

  async function renderShortsData(shortsData, renderItem, startsWith, options={}) {
    return new Promise(async (resolve, reject) => {
        try {

            if (!shortsData.data || shortsData.data.length === 0) {
                resolve(''); // No data to render, resolve with an empty string
                return;
            }
            
            let html = `<section class="mt-2 mb-4 viewAllSection ${options.homeClass??''}">
                          <div class="container-fluid">
                              <div class="row mt-1">
                                  <div class="col-md-12 shots-pad">
                                      <div class="hom_shorts_design">`;
            var i = 0;
            var j = 0;
            shortsData.data.forEach((item, item_key) => {
              j += 1;
              if (((j-1) >= startsWith) && (i < renderItem)) {
                if(item.type >= 4 && item.type < 8){
                  var url = "<?=base_url('content-detail?id=')?>" + item.enc_id??item.id;
                }else{
                  var url = "<?=base_url('play-video?id=')?>" + item.enc_id??item.id;
                }
                
                i += 1;
                html += `<div class="shorts_img " data-play="${item.type}" data-id="${item.id}" data-title="${item.title}" data-poster_url="${item.poster_url}" data-is_drm_protected="${item.is_drm_protected}" data-file_url="${item.file_url}" data-vdc_id="${item.vdc_id}" data-media_id="${item.video_id}">
                            <a href="${url}">
                                <div class="shorts_para feed-${item.id}">
                                    <img src="${(item.type==5||item.type==4)?((item.thumbnail)?(item.thumbnail):"<?=base_url('assets/images/placeholder.png')?>"):((item.poster_url)?(item.poster_url):"<?=base_url('assets/images/placeholder.png')?>")}" class="img-fluid as4" alt="${item.title}">
                                </div>
                                <div class="shorts_dets_li">
                                    <div class="shorttxt d-flex align-items-center">
                                        <h4>${item.title}</h4>
                                        <a href="${url}" class="viewbtn_al d-flex align-items-center"><span>Know More </span><i class="fas fa-chevron-right ms-2"></i></a>
                                    </div><p>
                                
                                ${
                                  [
                                    //item.category_title ? item.category_title : '',
                                    item.genres ? item.genres.split(',')[0] : '',
                                    item.genres ? (item.genres.split(',')[1]?item.genres.split(',')[1]:'') : '',
                                    (item.released_on && item.released_on != 0 && false) ? item.released_on.split('-')[0] : '',
                                    //item.video_time ? convertTime(item.video_time) : ''
                                  ]
                                  .filter(Boolean)
                                  .join("<span class='dotspan'>●</span>")
                                }
                                </p></div>
                            </a>
                          </div>`;
              }
            });

            html += `</div></div></div></div></section>`;
            resolve(html); // Resolve with the constructed HTML
        } catch (error) {
            reject(error); // Reject the promise in case of an error
        }
    });
}


