  function matomo(user, type, titles, geners = '') {
    if(geners.length < 1){
      queueTrackingDataWithDelay('trackEvent', [user,type,titles],0);      
    }else{
      queueTrackingDataWithDelay('trackEvent', [user,type,titles],0);  
      queueTrackingDataWithDelay('trackContentImpression', [titles, geners],100);
      queueTrackingDataWithDelay('trackContentInteraction', [user + '/' +type, titles,geners],200);

    }
    
  }

  function matomo_like(user, type, titles, geners = '') {
