<script>
  function shortenEmail(email_id) {
    var parts = email_id.split('@');
    var username = parts[0];
    var domain = parts[1];
    //var shortenedUsername = username.substring(0, 3) + '***';
    let visibile_char = 5;
    let star_string = '';
    // if (username.length > visibile_char) {
    //   star_string = "***";
    // }
    if (username.length > visibile_char) {
      star_string = "****";
      // if (username.length <= 10) {
      //   let star_count = 10 - username.length;
      //   star_string = "*";
      //   for ($i = 0; $i > star_count; $i++) {
      //     star_string += star_string;
      //   }
      // }
    }
    let shortenedUsername = username.substring(0, visibile_char) + star_string;

    return shortenedUsername + '@' + domain;
  }

