<script>
    async function get_encode_id(id){
        try {
            let encoded_string = "";
            await $.ajax({
                type: 'POST',
                url: '<?= base_url('/web/Epg/get_encode_id'); ?>',
                data: {id: id},
                beforeSend: function() {
                    $('#overlayonajaxhit').show(); // Show loader before sending the request
                },
                success: function(response) { 
                    if (response) {
                        encoded_string = response;
                    }
                },
                complete: function() {
                    $('#overlayonajaxhit').hide(); // Hide loader after request completion
                }
            });
            return encoded_string;
        } catch (error) {
            console.log(error);
            return false;
        }
    }

    async function get_channel_details(program_id, channel_status, program_title="", program_timing="", program_banner = "", urltype=1){
        //console.log("encoded",id); 
        //console.log("program_banner",program_banner);
        let redirect_url = '#';
        if(urltype==1){
          let id = await get_encode_id(program_id);
          redirect_url = "<?= base_url('pb_live_details?id=');?>"+id;
        }
        
        if(channel_status == "upcoming"){
            let program_date = moment.unix(program_timing).format('ddd, DD MMMM');
            let program_time = moment.unix(program_timing).format('hh:mm A');
            $('.epg_program_title').text(program_title);
            $('.epg_program_date').text(program_date);
            $('.epg_program_time').text(program_time);
            $('.epg_program_url').attr('href',redirect_url);
            $('.epg_program_image').attr('src', program_banner);
            $('#upcominModal').modal('show');
        } else if(channel_status == "past"){
            //window.location.href = redirect_url;
            $("#overlayonajaxhit").show();
            urls_call(redirect_url);
        } else {
            //window.location.href = redirect_url;
            $("#overlayonajaxhit").show();
            urls_call(redirect_url);
        }
    }
    

