      try {
        //alert('delete');
        var cache = await caches.open('appCache');
        var cachedResponse = await cache.match(key);
      // console.log(cachedResponse);
        if (cachedResponse) {
          await cache.delete(key);
        }
      } catch (err) {
      //  console.warn('Error :', err);
      }
    }
 


