<script>
  $(document).ready(async function(){ 
    let pages = await get_static_pages();
    //console.log("static_pages",static_pages);
    let static_page_html = "";
    if(pages.static_pages && pages.static_pages.length){
      for(let each_page of pages.static_pages){
        let page_title = each_page.title;
        //console.log("local_strings",local_strings);
        if(local_strings && local_strings_en){
            let local_string_key = findKeyByValue(local_strings_en,page_title);
            if(local_string_key){
                page_title = local_strings.hasOwnProperty(local_string_key)?local_strings[local_string_key]:page_title
            }
        }

        let url = each_page.page;
        let page_url = "<?= site_url();?>" + url.split(' ').join('-');
        //console.log("page_url",page_url);
        static_page_html += '<li><a href="'+page_url+'">'+ page_title +'</a></li>';
      }
    }
    $(".footer_link_sec").html(static_page_html);

    let contact = "", email = {};
    if(pages.help_support){ 
      contact = (pages.help_support.hasOwnProperty('contact'))?pages.help_support.contact:"";
      email = (pages.help_support.hasOwnProperty('email'))?pages.help_support.email:"";
    }
    $('.mobT').attr('href','tel:+91'+contact);
    $('.mobT').text(contact);
    $('.contTittle .text-blue').attr('href','mailto: '+email);
    $('.contTittle .text-blue').text(email);

  });

  async function get_static_pages(){ 
    let return_data = {
      static_pages:[],
      help_support:{}
    };
    let static_pages = await fetchCacheData('static_pages'); 
    //console.log(static_pages.data);
    if(static_pages && static_pages.hasOwnProperty('data')){
      return_data.static_pages = static_pages.data;
    }
    let hns = await fetchCacheData('help_support'); 
    if(hns && hns.hasOwnProperty('data')){
      return_data.help_support = hns.data;
    }
    return return_data;
  }


  function queueTrackingDataWithDelay(method, params, delay) {
      setTimeout(() => {
          queueTrackingData(method, params);
      }, delay);
  }

</script>

