<script>
  if ('permissions' in navigator) {
    navigator.permissions.query({ name: 'notifications' }).then(function(permissionStatus) {
        //console.log('Initial Notification permission status:', permissionStatus.state);
        //alert(permissionStatus.state);
        let cur_status = "<?= ($this->session->userdata('toggle_check_set')==true)?true:false; ?>";
        if(cur_status == false && permissionStatus.state == "granted"){
            $.ajax({
                type: 'POST',
                url: '<?= base_url('/web/home/notification_toggle'); ?>',
                data: {
                    toggle_status: 1
                },
                dataType: "json",
                success: function(data) {
                  if(data.hasOwnProperty('status') && data.status == true){
                    localStorage.setItem('pb_session', (data.token));
                  }
                }
            });
        }
        // Listen for changes to the permission status
        permissionStatus.onchange = function() {
            let permission_status = this.state;
            var isChecked = (permission_status == "granted") ? 1 : 0;
            $.ajax({
                type: 'POST',
                url: '<?= base_url('/web/home/notification_toggle'); ?>',
                data: {
                    toggle_status: isChecked
                },
                dataType: "json",
                success: function(data) {
                  if(data.hasOwnProperty('status') && data.status == true){
                    localStorage.setItem('pb_session', (data.token));
                  }
                }
            });
        }; 
    });
}

 function filterFeedData(feedType,name=''){
  queueTrackingData('trackEvent', ["HomePage", "Select", "Tag("+feedType+"/"+name+")"]);
    localStorage.setItem('feedType',feedType);
    localStorage.setItem('feedTypename',name);

