 }

 function component_url(action, id){
    // create dynamic url based 
    let url;
    if(items.component_action == 'homePage'){
        url = "<?= base_url('provider?id=') ?>"+id;
    }else if(items.component_action == 'contentPartners'){
        url = "<?= base_url("provider?id=") ?>"+id;
    }else if(items.component_action == 'sectionList'){
        url = "<?= base_url("dashboard-details?category_id=") ?>"+id;
    }else if(action == 'flatList'){
        url = "<?= base_url('gener_list?genre=') ?>"+id;
    }
    return url
}


var hoverFeedTimeout;
var feedPlayer;
let drmDataFetched = true; // Store DRM data fetched per item

$(document).on('mouseenter', '.shorts_img', async function() {
  let play = $(this).data('play');
  if(play != 0){
    return false;
  }
  clearTimeout(hoverFeedTimeout);
  if(!drmDataFetched){
    return false;
  }
  drmDataFetched = false;
  let id = $(this).data('id');
  let poster_url = $(this).data('poster_url');
  hoverFeedTimeout = setTimeout(() => {
    var html = $('.feed-' + id).html();
    html += `<div class="video-container position-relative d-none">
                  <video class="img-fluid as4 mb-0" poster="${poster_url}" id="feedElement" disablePictureInPicture autoplay muted></video>
                  <div class="volume_banner_dt" id="mute-toltip-00" >
                      <a href="javascript:void(0);" data-valumeType="card" class="homeFeed_volume card_volume d-block" data-id="00">`;
                      if(unmuteSpke == false){
                        html += `<img id="mute-icn" src="<?= base_url('assets/images/mute.svg') ?>" alt="mute" class="img-fluid">`;
                      }else{
                        html += `<img id="mute-icn" src="<?= base_url('assets/images/unmute.svg') ?>" alt="mute" class="img-fluid">`;
                      }
                    html  += `</a>
                  </div>
                  <input type="range" id="feedSeekBar" value="0" max="100" style="width: 100%;">
                </div>`;
    $('.feed-' + id).html(html);
  }, 100);

  let is_drm_protected = $(this).data('is_drm_protected');
  let file_url = $(this).data('file_url');
  let vdc_id = $(this).data('vdc_id');
  let media_id = $(this).data('media_id');
  let token = '';

  if (is_drm_protected == 1) {
    let res = await getDrmData(vdc_id, media_id);
    if (res.url && res.token) {
      file_url = res.url;
      token = res.token;
    }
  }

  let data = {
    'is_drm_protected': is_drm_protected,
    'file_url': file_url,
    'token': token
  };
  homeFeedPlayer(data);
});


$(document).on('mouseleave', '.shorts_img', function() {
  let play = $(this).data('play');
  if(play != 0){
    return false;
  }
  clearTimeout(hoverFeedTimeout);
  drmDataFetched = true;
  let title = $(this).data('title');
  let poster_url = $(this).data('poster_url');
  let id = $(this).data('id');
  let html = `<img src="${poster_url ? poster_url : "<?=base_url('assets/images/placeholder.png')?>"}" class="img-fluid as4" alt="${title}">`;
  $('.feed-' + id).html(html);
});

$(document).on('click', '.homeFeed_volume', function(){
  var videoElement = document.getElementById("feedElement");
  if (videoElement.muted) {
    unmuteSpke = true;
    videoElement.muted = false;
    var unmute_icon = base_url + 'assets/images/unmute.svg';
    $('#mute-icn').attr('src', unmute_icon);
    $('.card_volume img').attr('src', unmute_icon);
  } else {
    unmuteSpke = false;
    var mute_icon = base_url + 'assets/images/mute.svg';
    videoElement.muted = true;
    $('#mute-icn').attr('src', mute_icon);
    $('.card_volume img').attr('src', mute_icon);
  }
})

async function homeFeedPlayer(data){
    if (feedPlayer) {
      await feedPlayer.destroy();
    }
    var browser = 1;
    var videoElement = document.getElementById("feedElement");
    const feedSeekBar = document.getElementById('feedSeekBar');
    feedPlayer = new shaka.Player(videoElement);
    var fairplayCertUri = 'https://license-global.pallycon.com/ri/fpsKeyManager.do?siteId='+'<?=SITE_ID?>';
    var licenseURI = "<?= BASEURLAPI.BASEVERSION ?>"+'onRequestCreateVideoLicense';

    // videoElement.addEventListener('loadedmetadata', () => {
    //   feedSeekBar.max = videoElement.duration;
    // });

    // videoElement.addEventListener('timeupdate', () => {
    //   feedSeekBar.value = videoElement.currentTime;
    // });

    // feedSeekBar.addEventListener('click', (event) => {
    //   event.stopPropagation();
    //   event.preventDefault();
    //   videoElement.currentTime = feedSeekBar.value;
    // });

    var drmConfig = {
      servers: {
        "com.apple.fps": licenseURI,
        "com.widevine.alpha": licenseURI,
        // Add "com.microsoft.playready": licenseURI if needed
      },
      advanced: {}
    };

    // Configure DRM
    if (browser === 2) { // FairPlay DRM for Safari
      drmConfig.advanced['com.apple.fps'] = {
        serverCertificate: getFairplayCert(fairplayCertUri)
      };
    } else { // Widevine DRM for other browsers
      drmConfig.advanced['com.widevine.alpha'] = {
        videoRobustness: "SW_SECURE_DECODE",
        audioRobustness: "SW_SECURE_CRYPTO"
      };
    }

    // Configure player
    feedPlayer.configure({
      drm: drmConfig,
      streaming: {
        autoLowLatencyMode: true
      }
    });

    // Networking filters
    feedPlayer.getNetworkingEngine().registerRequestFilter(licenseRequestFilter);
    // feedPlayer.getNetworkingEngine().registerResponseFilter(adTrackingResponseFilter);
    if (browser === 2) {
      feedPlayer.getNetworkingEngine().registerResponseFilter(fairplayLicenseResponseFilter);
    }

    // Function to get FairPlay certificate
    function getFairplayCert(uri) {
      const xmlhttp = new XMLHttpRequest();
      xmlhttp.open("GET", uri, false);
      xmlhttp.send();
      return shaka.util.Uint8ArrayUtils.fromBase64(xmlhttp.responseText);
    }

    // License request filter
    function licenseRequestFilter(type, request) {
      if (type === shaka.net.NetworkingEngine.RequestType.LICENSE) {
        request.headers["pallycon-customdata-v2"] = data.token;
        if (browser === 2) { // FairPlay specific
          const originalPayload = new Uint8Array(request.body);
          const base64Payload = shaka.util.Uint8ArrayUtils.toBase64(originalPayload);
          request.body = shaka.util.StringUtils.toUTF8('spc=' + encodeURIComponent(base64Payload));
          request.headers['Content-Type'] = 'application/x-www-form-urlencoded';
        }
      }
    }

    // FairPlay license response filter
    function fairplayLicenseResponseFilter(type, response) {
      if (type === shaka.net.NetworkingEngine.RequestType.LICENSE) {
        const responseText = shaka.util.StringUtils.fromUTF8(response.data).trim();
        response.data = shaka.util.Uint8ArrayUtils.fromBase64(responseText).buffer;
      }
    }
    await feedPlayer.load(data.file_url);
    const parentContainer = feedSeekBar.closest('.shorts_para');
    // const imgElement = parentContainer.querySelector('img');
    const imgElement = Array.from(parentContainer.children).find(child => child.tagName === 'IMG');

    if (imgElement) {
      imgElement.remove(); // Remove the <img> element if it exists
    }
    const videoContainer = feedSeekBar.closest('.video-container');
    try {
      videoElement.addEventListener('loadedmetadata', () => {
          if (Number(nskipable_start) > 0) {
              videoElement.currentTime = Number(nskipable_start);
          }
      });

      videoElement.addEventListener('timeupdate', function onTimeUpdate() {
          if (Number(nskipable_end) > 0 && ((videoElement.duration-Number(nskipable_end)) > Number(nskipable_start)) && videoElement.currentTime >= (videoElement.duration-Number(nskipable_end))) {
              videoElement.pause();
              videoElement.currentTime = Number(nskipable_start);
              videoElement.removeEventListener('timeupdate', onTimeUpdate);
          }
      });
      videoElement.play();
      if (unmuteSpke) {
        videoElement.muted = false;
      } else {
        videoElement.muted = true;
      }
      
        if (imgElement) {
          imgElement.remove(); // Remove the <img> element from the DOM
        }
        $('.shorts_img .volume_banner_dt').show()
      videoContainer.classList.remove('d-none');
    } catch (error) {
      videoContainer.remove();
      console.log(error);
    }
}

</script>
